 async function auth(e:FormEvent){e.preventDefault();if(authBusy||authLocked)return;setAuthLocked(true);window.setTimeout(()=>setAuthLocked(false),3000);if(!supabaseReady){notify('Manca la chiave pubblica Supabase nelle impostazioni del sito.');return}if(authMode==='register'&&!accepted){notify('Accetta Privacy e Termini per continuare.');return}if(authMode==='register'&&(!turnstileSiteKey||!captchaToken)){notify('La verifica anti-bot deve essere configurata e completata per registrarti.');return}if(turnstileSiteKey&&!captchaToken){notify('Completa la verifica anti-bot per continuare.');return}setAuthBusy(true);try{const client=requireSupabase();if(authMode==='register'){const {data,error}=await client.auth.signUp({email,password,options:{captchaToken:captchaToken||undefined,emailRedirectTo:location.origin,data:{privacy_policy_version:'2026-11-03',terms_version:'2026-11-03',accepted_privacy:accepted}}});if(error)throw error;if(data.session)await client.functions.invoke('quiz-api',{body:{action:'consent',accepted:true}});notify('Controlla la tua email per confermare la registrazione.')}else if(authMode==='reset'){const {error}=await client.auth.resetPasswordForEmail(email,{redirectTo:location.origin,captchaToken:captchaToken||undefined});if(error)throw error;notify('Se l’email è registrata, riceverai il link di recupero.')}else{const {error}=await client.auth.signInWithPassword({email,password,options:{captchaToken:captchaToken||undefined}});if(error)throw error;notify('Accesso effettuato.');setPage('home')}}catch(err){notify(err instanceof Error?err.message:'Operazione non riuscita.')}finally{setAuthBusy(false);setCaptchaToken('');setCaptchaReset(v=>v+1)}}
