 async function submit(){if(!choice||!current||revealed)return;if(reviewMode){const good=choice===current.risposta_corretta;setAnswerFeedback({correct:good,correctAnswer:current.risposta_corretta||'',explanation:current.spiegazione||null});if(good)setCorrect(v=>v+1);else setWrong(v=>v+1);setRevealed(true);return}if(!attemptId||!supabase)return;setBusy(true);try{let data:any=null;for(let retry=0;retry<2;retry++){const result=await supabase.functions.invoke('quiz-api',{body:{action:'answer',attemptId,questionId:current.id,selectedAnswer:choice}});if(!result.error){data=result.data;break}if(retry===1)throw result.error;await new Promise(resolve=>window.setTimeout(resolve,700))}if(data?.error)throw new Error(data.error);const good=Boolean(data.correct);setAnswerFeedback({correct:good,correctAnswer:data.correctAnswer,explanation:data.explanation});if(good)setCorrect(v=>v+1);else{setWrong(v=>v+1);setWrongQuestions(v=>[...v.filter(q=>q.id!==current.id),{...current,risposta_corretta:data.correctAnswer,spiegazione:data.explanation}])}try{const ctx=new AudioContext(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);osc.frequency.value=good?760:220;gain.gain.value=.035;osc.start();osc.stop(ctx.currentTime+.13)}catch{}setRevealed(true)}catch(err){notify(err instanceof Error?err.message:'Non è stato possibile salvare la risposta.')}finally{setBusy(false)}}
 function next(){if(index<questions.length-1){setIndex(v=>v+1);setChoice(null);setAnswerFeedback(null);setRevealed(false)}else void finish()}
 async function finish(){if(reviewMode){setQuestions([]);setStarted(null);setReviewMode(false);setPage('progress');notify('Ripasso completato.');return}if(!attemptId||!supabase)return;try{const {data,error}=await supabase.functions.invoke('quiz-api',{body:{action:'finish',attemptId}});if(error)throw error;if(data?.error)throw new Error(data.error);const item:Attempt={id:attemptId,subject:subject?.nome||'Quiz',score:Number(data.score),total:Number(data.total),correct:Number(data.correct),wrong:Number(data.wrong),date:new Date().toISOString()};setHistory(v=>[item,...v.filter(x=>x.id!==item.id)]);localStorage.removeItem('smlquiz.active-quiz.v1');void supabase.functions.invoke('quiz-api',{body:{action:'weak-topics'}}).then(({data,error})=>{if(!error&&data?.topics)setWeakTopics(data.topics as WeakTopic[])});setReviewQuestions(wrongQuestions);setWrongQuestions([]);setQuestions([]);setStarted(null);setAttemptId(null);setPage('progress');notify('Quiz completato: '+item.score.toFixed(2)+' punti.');void refreshWallet()}catch(err){notify(err instanceof Error?err.message:'Errore nel salvataggio del quiz.')}}
 function shareUrl(h:Attempt){const url=new URL(location.origin);url.searchParams.set('share','quiz');url.searchParams.set('subject',h.subject);url.searchParams.set('score',h.score.toFixed(2));url.searchParams.set('correct',String(h.correct));url.searchParams.set('total',String(h.total));return url.toString()}
 async function copyShare(h:Attempt){const url=shareUrl(h);try{await navigator.clipboard.writeText(url);notify('Link del risultato copiato.')}catch{const field=document.createElement('textarea');field.value=url;field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();const copied=document.execCommand('copy');field.remove();notify(copied?'Link del risultato copiato.':'Non è stato possibile copiare il link.')}}
 function averageWeighted(){const valid=exams.map(e=>({g:Number(e.grade),c:Number(e.cfu)})).filter(e=>e.g>=18&&e.g<=30&&e.c>0);const c=valid.reduce((a,b)=>a+b.c,0);return c?(valid.reduce((a,b)=>a+b.g*b.c,0)/c).toFixed(2):'—'}
